declare module 'virtual:pawsport-courses' {
  /** A live course, from courses.json and content/<id>/journey.yaml (generated by vite.hub.config.ts). */
  export interface HubCourse {
    id: string
    name: string
    native: string
    flag: string
    slug: string
    /** BCP 47 tag of the target language (for the native name). */
    locale: string
    /** Absolute URL of the course, e.g. /aprende/spanish/. */
    href: string
    /** The course's IndexedDB (same origin as the hub). */
    dbName: string
    country: string
    pitch: string
    /** One region per level, in journey order. */
    regions: { level: string; name: string }[]
  }
  const courses: HubCourse[]
  export default courses
}
